/**
 * Computes the rewind offset for a circular buffer.
 * Prevents integer underflow by ensuring head >= rewind_bytes.
 */
size_t compute_rewind_offset(size_t head, size_t rewind_bytes, size_t capacity) {
    if (rewind_bytes > head) {
        // Handle underflow by wrapping around the circular buffer
        return (head + capacity - (rewind_bytes % capacity)) % capacity;
    }
    return head - rewind_bytes;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    if (size < sizeof(size_t) * 3) {
        return 0;
    }

