    // Extract inputs from fuzzer data
    const size_t *ptr = reinterpret_cast<const size_t *>(data);
    head = ptr[0];
    rewind_bytes = ptr[1];
    capacity = ptr[2];

    // Ensure capacity is non-zero to avoid division by zero
    if (capacity == 0) {
        capacity = 1;
    }

    // Execute the function under test
    compute_rewind_offset(head, rewind_bytes, capacity);

    return 0;
}

